import os,requests,json,re
url=os.environ['GALAXY_URL'].rstrip('/')
with open(os.environ['GALAXY_API_KEY_FILE']) as f:key=f.read().strip()
s=requests.Session(); s.headers.update({'x-api-key':key})
for p in ['/api/schema/openapi.json','/api/schema','/api/openapi.json','/api/docs']:
 r=s.get(url+p,timeout=30)
 print(p,r.status_code,r.headers.get('content-type'),r.text[:100].replace('\\n',' '))
 if r.status_code==200 and 'json' in r.headers.get('content-type',''):
  data=r.json();
  for path in data.get('paths',{}):
   if any(term in path.lower() for term in ['tool','source','user']):
    if any(term in path.lower() for term in ['source','user','tool']): print(path)
  break
PY"

